func unsafeMap(src interface{}) map[string]interface{} {
	srcValue := reflect.ValueOf(src)
	mt := reflect.TypeOf(map[string]interface{}{})
	if !srcValue.Type().AssignableTo(mt) {
		return nil
	}
	
	src = srcValue.Interface()
	var v unsafe.Pointer = (unsafe.Pointer)(unsafe.Pointer(uintptr(unsafe.Pointer(&src)) + unsafe.Sizeof(int(0))))
	var dst *map[string]interface{} = (*map[string]interface{})(v)
